import React, { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { MousePointerClick } from "lucide-react";
import { useLang } from "../context/LanguageContext";
import { t } from "../lib/content";

/*
 * Signature moment: a full-screen elevator whose doors open on one click,
 * revealing the hero content behind them.
 */
export const ElevatorStage = ({ children }) => {
  const { lang } = useLang();
  const reduce = useReducedMotion();
  const [isOpen, setIsOpen] = useState(false);

  if (reduce) {
    return <div className="relative min-h-screen">{children}</div>;
  }

  return (
    <section data-testid="elevator-stage" className="relative h-screen overflow-hidden bg-white">
        {/* Hero behind the doors */}
        <motion.div
          animate={{ scale: isOpen ? 1 : 1.18, opacity: isOpen ? 1 : 0.25 }}
          transition={{ duration: 0.9, ease: "easeOut" }}
          className="absolute inset-0"
        >
          {children}
        </motion.div>

        {/* LEFT DOOR */}
        <motion.div
          animate={{ x: isOpen ? "-101%" : "0%" }}
          transition={{ duration: 1.15, ease: [0.76, 0, 0.24, 1] }}
          className="door-metal absolute left-0 top-0 h-full w-1/2 z-40 shadow-[inset_-40px_0_60px_-30px_rgba(0,0,0,0.35)]"
        >
          <DoorFace side="left" lang={lang} />
        </motion.div>

        {/* RIGHT DOOR */}
        <motion.div
          animate={{ x: isOpen ? "101%" : "0%" }}
          transition={{ duration: 1.15, ease: [0.76, 0, 0.24, 1] }}
          className="door-metal absolute right-0 top-0 h-full w-1/2 z-40 shadow-[inset_40px_0_60px_-30px_rgba(0,0,0,0.35)]"
        >
          <DoorFace side="right" lang={lang} />
        </motion.div>

        {/* Center seam */}
        <motion.div
          animate={{ opacity: isOpen ? 0 : 1 }}
          transition={{ duration: 0.6 }}
          className="absolute left-1/2 top-0 h-full w-[3px] -translate-x-1/2 bg-gradient-to-b from-brick/0 via-brick to-brick/0 z-50 pointer-events-none"
        />

        {/* Click target and hint */}
        <button
          type="button"
          onClick={() => setIsOpen(true)}
          disabled={isOpen}
          aria-label={t[lang].doorHint}
          data-testid="elevator-open-button"
          className={`absolute inset-0 z-[60] cursor-pointer ${isOpen ? "pointer-events-none" : ""}`}
        />
        <motion.div
          animate={{ opacity: isOpen ? 0 : 1, y: isOpen ? 12 : 0 }}
          transition={{ duration: 0.3 }}
          className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 z-[70] flex flex-col items-center gap-2 pointer-events-none"
        >
          <span className="text-xs uppercase tracking-[0.3em] text-ink/70 font-semibold">
            {t[lang].doorHint}
          </span>
          <motion.div
            animate={{ y: [0, 8, 0] }}
            transition={{ repeat: Infinity, duration: 1.6, ease: "easeInOut" }}
          >
            <MousePointerClick size={22} className="text-brick" />
          </motion.div>
        </motion.div>
    </section>
  );
};

const DoorFace = ({ side, lang }) => (
  <div className="relative h-full w-full overflow-hidden">
    {/* vertical brushed grooves */}
    <div className="absolute inset-0 opacity-40 [background:repeating-linear-gradient(90deg,transparent,transparent_38px,rgba(0,0,0,0.06)_39px,transparent_40px)]" />

    {/* Floor indicator near top-center (edge that meets seam) */}
    <div className={`absolute top-[12%] ${side === "left" ? "right-8" : "left-8"} flex flex-col items-center gap-3`}>
      <div className="bg-ink text-brick font-display text-2xl md:text-4xl tracking-widest px-4 py-2 md:px-6 md:py-3 border border-white/10 shadow-lg">
        {side === "left" ? "▲" : "L E"}
      </div>
    </div>

    {/*
      One single logo centered on the whole screen (its center sits on the
      door seam). Each door only shows half of it, so it splits in two as the
      doors slide apart.
    */}
    <div
      className="absolute top-1/2 -translate-y-1/2 h-[58vh] w-[58vh]"
      style={side === "left" ? { right: "-29vh" } : { left: "-29vh" }}
    >
      <img src="/liftexpress-showroom-logo.png" alt="" className="h-full w-full object-contain drop-shadow-sm" />
    </div>

    {/* subtle top light strip */}
    <div className="absolute top-0 left-0 right-0 h-1.5 bg-gradient-to-r from-transparent via-white to-transparent opacity-70" />
  </div>
);
